<?php
declare(strict_types=1); namespace Joomleague\Component\Joomleague\Administrator\Table; defined('_JEXEC') or die;
use Joomla\CMS\Language\Text; use Joomla\CMS\Table\Table; use Joomla\Database\DatabaseDriver; use Joomla\Database\ParameterType; use Joomla\String\StringHelper;
final class EventTable extends Table { protected $_supportNullValue=true; protected $_trackAssets=false; public function __construct(DatabaseDriver $db){parent::__construct('#__joomleague_event_type','id',$db);$this->_trackAssets=false;} public function check():bool { $this->name=StringHelper::trim((string)$this->name); $this->code=strtolower(StringHelper::trim((string)$this->code)); $this->person_type=StringHelper::trim((string)($this->person_type??''))?:null; $this->score_target=StringHelper::trim((string)($this->score_target??''))?:null; $this->score_delta=($this->score_delta??'')===''?null:(float)$this->score_delta; if((int)$this->sport_type_id<1||$this->name===''){ $this->setError(Text::_('COM_JOOMLEAGUE_ERROR_EVENT_REQUIRED'));return false;} foreach([$this->code,$this->person_type,$this->score_target] as $i=>$code) if($code!==null&&preg_match('/^[a-z][a-z0-9_]{0,99}$/',$code)!==1){$this->setError(Text::_('COM_JOOMLEAGUE_ERROR_EXTENSIBLE_CODE_INVALID'));return false;} $db=$this->getDatabase();$id=(int)$this->id;$sid=(int)$this->sport_type_id;$query=$db->getQuery(true)->select('COUNT(*)')->from($db->quoteName('#__joomleague_event_type'))->where('sport_type_id=:sid')->where('code=:code')->where('id<>:id')->bind(':sid',$sid,ParameterType::INTEGER)->bind(':code',$this->code)->bind(':id',$id,ParameterType::INTEGER);if((int)$db->setQuery($query)->loadResult()>0){$this->setError(Text::_('COM_JOOMLEAGUE_ERROR_EVENT_CODE_DUPLICATE'));return false;}return parent::check();} }
